/* Pure chemistry rules for the explicitly limited school Lewis model. */
const chemElements={H:{name:'Hydrogen',valence:1,bonds:1,color:'#edf1e9'},C:{name:'Karbon',valence:4,bonds:4,color:'#c5d4ce'},N:{name:'Nitrogen',valence:5,bonds:3,color:'#b9d4ec'},O:{name:'Oksygen',valence:6,bonds:2,color:'#f3b3a4'},F:{name:'Fluor',valence:7,bonds:1,color:'#c6e4b2'},P:{name:'Fosfor',valence:5,bonds:3,color:'#f2c291'},S:{name:'Svovel',valence:6,bonds:2,color:'#efdf94'},Cl:{name:'Klor',valence:7,bonds:1,color:'#b6dda4'},Br:{name:'Brom',valence:7,bonds:1,color:'#dab5a2'},I:{name:'Jod',valence:7,bonds:1,color:'#d7bfe9'},B:{name:'Bor',valence:3,bonds:3,color:'#ead4bc'},Si:{name:'Silisium',valence:4,bonds:4,color:'#d9d9ba'}};
const saltElements={Li:{name:'Litium',valence:1,target:1},Na:{name:'Natrium',valence:1,target:1},K:{name:'Kalium',valence:1,target:1},Mg:{name:'Magnesium',valence:2,target:2},Ca:{name:'Kalsium',valence:2,target:2},Al:{name:'Aluminium',valence:3,target:3},F:{name:'Fluor',valence:7,target:-1},Cl:{name:'Klor',valence:7,target:-1},Br:{name:'Brom',valence:7,target:-1},I:{name:'Jod',valence:7,target:-1},O:{name:'Oksygen',valence:6,target:-2},S:{name:'Svovel',valence:6,target:-2}};
// Transition-metal dots count electrons transferred to the chosen ion, not an outer shell.
Object.assign(saltElements,{
 FeII:{symbol:'Fe',name:'Jern → Fe²⁺',valence:2,target:2,transition:true},
 FeIII:{symbol:'Fe',name:'Jern → Fe³⁺',valence:3,target:3,transition:true},
 CuI:{symbol:'Cu',name:'Kobber → Cu⁺',valence:1,target:1,transition:true},
 CuII:{symbol:'Cu',name:'Kobber → Cu²⁺',valence:2,target:2,transition:true},
 Zn:{name:'Sink',valence:2,target:2,transition:true},
 Ag:{name:'Sølv',valence:1,target:1,transition:true}
});
function saltElementKey(symbol,charge){return Object.keys(saltElements).find(k=>(saltElements[k].symbol||k)===symbol&&saltElements[k].target===charge)}
function chemCounts(atoms){const out={};atoms.forEach(a=>out[a.element]=(out[a.element]||0)+1);return out}
function chemComposition(atoms){return Object.entries(chemCounts(atoms)).sort(([a],[b])=>a.localeCompare(b)).map(([s,n])=>s+':'+n).join('|')}
function chemFormula(atoms){const c=chemCounts(atoms),keys=Object.keys(c).sort();if(c.C){keys.splice(keys.indexOf('C'),1);keys.unshift('C');if(c.H){keys.splice(keys.indexOf('H'),1);keys.splice(1,0,'H')}}return keys.map(k=>k+(c[k]>1?c[k]:'')).join('')}
function chemBondCounts(atoms,bonds){const c=atoms.map(()=>0);bonds.forEach(([a,b,n])=>{c[a]+=n;c[b]+=n});return c}
function chemConnected(atoms,bonds){if(!atoms.length)return false;const seen=new Set([0]);let changed=true;while(changed){changed=false;bonds.forEach(([a,b])=>{if(seen.has(a)&&!seen.has(b)){seen.add(b);changed=true}if(seen.has(b)&&!seen.has(a)){seen.add(a);changed=true}})}return seen.size===atoms.length}
function chemValidate(atoms,bonds){const used=chemBondCounts(atoms,bonds);if(!atoms.length)return{complete:false,message:'Legg til atomer eller velg en byggeoppgave.'};if(atoms.some(a=>!chemElements[a.element]))return{complete:false,message:'Dette grunnstoffet støttes ikke av den enkle bindingsmodellen.'};if(used.some((u,i)=>u>chemElements[atoms[i].element].bonds))return{complete:false,message:'Et atom har flere bindinger enn modellen tillater.'};const missing=used.reduce((s,u,i)=>s+chemElements[atoms[i].element].bonds-u,0);if(missing)return{complete:false,missing,message:`${missing} ${missing===1?'ledig bindingselektron':'ledige bindingselektroner'}. Par et elektron med et elektron på et annet atom.`};if(!chemConnected(atoms,bonds))return{complete:false,message:'Du har flere atskilte molekyler. Verkstedet gjenkjenner ett sammenhengende molekyl om gangen.'};return{complete:true,message:'Alle bindingsplasser er fylt i denne Lewis-modellen.'}}
function chemCanBond(atoms,bonds,a,b){if(a===b||!atoms[a]||!atoms[b])return false;const counts=chemBondCounts(atoms,bonds),order=bonds.find(v=>(v[0]===a&&v[1]===b)||(v[0]===b&&v[1]===a))?.[2]||0;return order<3&&counts[a]<chemElements[atoms[a].element].bonds&&counts[b]<chemElements[atoms[b].element].bonds}
function chemAddBond(atoms,bonds,a,b){if(!chemCanBond(atoms,bonds,a,b))return false;const edge=bonds.find(v=>(v[0]===a&&v[1]===b)||(v[0]===b&&v[1]===a));if(edge)edge[2]++;else bonds.push([a,b,1]);return true}
// Remove terminal H from matching graphs, retaining their counts in atom labels.
// This keeps recognition fast without confusing structural isomers.
function chemMatchGraph(mol){const keep=mol.atoms.map((a,i)=>a.element!=='H'?i:-1).filter(i=>i>=0);if(!keep.length)return{labels:mol.atoms.map(a=>a.element),edges:mol.bonds};const map=new Map(keep.map((old,i)=>[old,i])),hs=mol.atoms.map(()=>0);mol.bonds.forEach(([a,b,n])=>{if(mol.atoms[a].element==='H'&&mol.atoms[b].element!=='H')hs[b]+=n;if(mol.atoms[b].element==='H'&&mol.atoms[a].element!=='H')hs[a]+=n});return{labels:keep.map(i=>mol.atoms[i].element+':H'+hs[i]),edges:mol.bonds.filter(([a,b])=>map.has(a)&&map.has(b)).map(([a,b,n])=>[map.get(a),map.get(b),n])}}
function chemSameStructure(a,b){if(a.atoms.length!==b.atoms.length||a.bonds.length!==b.bonds.length||chemComposition(a.atoms)!==chemComposition(b.atoms))return false;const x=chemMatchGraph(a),y=chemMatchGraph(b),size=x.labels.length;if(size!==y.labels.length)return false;const matrix=g=>{const m=Array.from({length:size},()=>Array(size).fill(0));g.edges.forEach(([a,b,n])=>m[a][b]=m[b][a]=n);return m};const mx=matrix(x),my=matrix(y);const signature=(g,m,i)=>g.labels[i]+'|'+m[i].map((order,j)=>order?order+':'+g.labels[j]:'').filter(Boolean).sort().join(',');const sx=x.labels.map((_,i)=>signature(x,mx,i)),sy=y.labels.map((_,i)=>signature(y,my,i));if([...sx].sort().join(';')!==[...sy].sort().join(';'))return false;const candidates=sx.map(s=>sy.map((t,j)=>t===s?j:-1).filter(j=>j>=0));const order=candidates.map((_,i)=>i).sort((a,b)=>candidates[a].length-candidates[b].length||mx[b].filter(Boolean).length-mx[a].filter(Boolean).length);const mapping=Array(size).fill(-1),used=new Set();function visit(k){if(k===size)return true;const i=order[k];for(const j of candidates[i]){if(used.has(j))continue;let ok=true;for(let h=0;h<k;h++){const p=order[h];if(mx[i][p]!==my[j][mapping[p]]){ok=false;break}}if(!ok)continue;mapping[i]=j;used.add(j);if(visit(k+1))return true;used.delete(j);mapping[i]=-1}return false}return visit(0)}
function chemFindMolecule(atoms,bonds,bank){return bank.find(m=>!m.referenceOnly&&chemSameStructure({atoms,bonds},m))||null}
function saltTransfer(atoms,from,to){const a=atoms[from],b=atoms[to];if(!a||!b||a.kind!=='metal'||b.kind!=='nonmetal'||a.charge>=a.target||b.charge<=b.target)return false;a.charge++;b.charge--;return true}
function saltCharge(atoms){return atoms.reduce((n,a)=>n+a.charge,0)}
function saltMatch(atoms,bank){if(!atoms.length||saltCharge(atoms)!==0||atoms.some(a=>!a.charge||a.charge!==a.target))return null;const kinds=new Map();atoms.forEach(a=>{const k=a.symbol+':'+a.charge;kinds.set(k,(kinds.get(k)||0)+1)});if(kinds.size!==2)return null;return bank.find(s=>{const c=kinds.get(s.cation.symbol+':'+s.cation.charge),a=kinds.get(s.anion.symbol+':'+s.anion.charge);return c&&a&&c*s.ratio[1]===a*s.ratio[0]})||null}
if(typeof module!=='undefined')module.exports={chemElements,saltElements,saltElementKey,chemCounts,chemComposition,chemFormula,chemBondCounts,chemConnected,chemValidate,chemCanBond,chemAddBond,chemSameStructure,chemFindMolecule,saltTransfer,saltCharge,saltMatch};
